const crypto = require('crypto');

const input = $input.first().json;
const headers = input.headers ?? {};
const signature =
  headers['x-line-signature'] ??
  headers['X-Line-Signature'];
const channelSecret = $env.LINE_CHANNEL_SECRET;

if (!channelSecret) {
  throw new Error('LINE_CHANNEL_SECRET is not configured');
}
if (!signature) {
  throw new Error('Missing x-line-signature header');
}

const rawBody =
  typeof input.body === 'string'
    ? input.body
    : (
        typeof input.rawBody === 'string'
          ? input.rawBody
          : JSON.stringify(input.body ?? {})
      );

const expected = crypto
  .createHmac('sha256', channelSecret)
  .update(rawBody, 'utf8')
  .digest('base64');

const signatureBuffer = Buffer.from(signature);
const expectedBuffer = Buffer.from(expected);

if (
  signatureBuffer.length !== expectedBuffer.length ||
  !crypto.timingSafeEqual(signatureBuffer, expectedBuffer)
) {
  throw new Error('Invalid LINE webhook signature');
}

const body =
  typeof input.body === 'string'
    ? JSON.parse(input.body)
    : (input.body ?? {});

const events = Array.isArray(body.events) ? body.events : [];

return events
  .filter((event) => event.replyToken && event.source?.userId)
  .map((event) => {
    let messageText = '';

    if (event.type === 'message') {
      messageText =
        event.message?.type === 'text'
          ? (event.message.text ?? '')
          : `[${event.message?.type ?? 'message'}]`;
    } else if (event.type === 'postback') {
      messageText = event.postback?.data ?? '[postback]';
    } else {
      messageText = `[${event.type ?? 'event'}]`;
    }

    return {
      json: {
        lineUserId: event.source.userId,
        replyToken: event.replyToken,
        messageText,
        webhookEventId: event.webhookEventId ?? null,
        isRedelivery:
          event.deliveryContext?.isRedelivery ?? false
      }
    };
  });

const MAINTENANCE_MESSAGE = '系統目前正在維護中，工程師正在處理，請稍後再試。';
const event = $('Verify Signature and Extract Events').item.json;
const recognition = $json ?? {};

const hasRecognitionError = Boolean(
  recognition.error ||
  recognition.message?.error ||
  (typeof recognition.statusCode === 'number' && recognition.statusCode >= 400)
);

if (hasRecognitionError) {
  return [{
    json: {
      immediateReply: true,
      businessFound: false,
      replyToken: event.replyToken,
      messages: [{ type: 'text', text: MAINTENANCE_MESSAGE }],
      errorStage: 'client-recognition'
    }
  }];
}

const businessFound = Boolean(
  recognition.business_found &&
  recognition.business_id &&
  recognition.business_name
);

const noticeMessages = businessFound
  ? []
  : [{
      type: 'text',
      text: `你的 LINE ID 是 ${event.lineUserId}。系統發現你尚未登記店家資料，請聯絡後台人員進行店家的註冊。`
    }];

return [{
  json: {
    immediateReply: false,
    businessFound,
    replyToken: event.replyToken,
    lineUserId: event.lineUserId,
    messageText: event.messageText,
    webhookEventId: event.webhookEventId,
    noticeMessages,
    clientRecognition: {
      client_registered: Boolean(recognition.client_registered ?? recognition.client_found),
      client_created: Boolean(recognition.client_created),
      client_found: Boolean(recognition.client_found),
      client_id: recognition.client_id ?? null,
      business_found: Boolean(recognition.business_found),
      business_id: recognition.business_id ?? null,
      business_name: recognition.business_name ?? null,
      branch_name: recognition.branch_name ?? null
    }
  }
}];

const item = $json;
const recognition = item.clientRecognition ?? {};
const reportPayload = {
  line_user_id: item.lineUserId,
  message_text: item.messageText,
  webhook_event_id: item.webhookEventId,
  refresh: false
};

if (recognition.business_id) {
  reportPayload.business_id = recognition.business_id;
}
if (recognition.business_name) {
  reportPayload.business_name = recognition.business_name;
}

return [{
  json: {
    replyToken: item.replyToken,
    noticeMessages: [],
    clientRecognition: recognition,
    reportMode: 'registered_client_business',
    reportPayload
  }
}];

const item = $json;
const reportPayload = {
  line_user_id: item.lineUserId,
  message_text: item.messageText,
  webhook_event_id: item.webhookEventId,
  refresh: false
};

return [{
  json: {
    replyToken: item.replyToken,
    noticeMessages: item.noticeMessages ?? [],
    clientRecognition: item.clientRecognition ?? {},
    reportMode: 'demo_business_fallback',
    reportPayload
  }
}];

const MAINTENANCE_MESSAGE = '系統目前正在維護中，工程師正在處理，請稍後再試。';
const request = $('Prepare Report Request').item.json;
const backend = $json ?? {};

const hasReportError = Boolean(
  backend.error ||
  backend.message?.error ||
  (typeof backend.statusCode === 'number' && backend.statusCode >= 400)
);

let messages = backend.line_messages;

if (hasReportError || !Array.isArray(messages) || messages.length === 0) {
  messages = [{ type: 'text', text: MAINTENANCE_MESSAGE }];
} else {
  messages = [
    ...(Array.isArray(request.noticeMessages) ? request.noticeMessages : []),
    ...messages
  ].slice(0, 5);
}

return [{
  json: {
    replyToken: request.replyToken,
    messages
  }
}];
